/**
 * Private helpers that turn stored rows into the hrefs the App Router serves.
 *
 * Alerts and search hits both link into the dashboard, and the dashboard's
 * routes are keyed by slugs and issue numbers, never by row ids — so every
 * link has to be resolved from the rows. The path shapes themselves live in
 * `@/lib/url`; nothing here concatenates a path by hand.
 */
import { issuePath, orgPath, projectPath, settingsPath } from "@/lib/url";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import type { CommentId, IssueId, OrgId, ProjectId } from "@/types/common";

/** Where a link lands when the row it points at can no longer be found. */
const ORG_PICKER_PATH = "/orgs";

async function slugOf(orgId: OrgId): Promise<string | null> {
  const org = await orgRepo.findOrgById(orgId);
  return org ? org.slug : null;
}

/** The organization's dashboard root. */
export async function orgHref(orgId: OrgId): Promise<string> {
  const slug = await slugOf(orgId);
  return slug === null ? ORG_PICKER_PATH : orgPath(slug);
}

/** A settings tab, e.g. `members` or `billing`. */
export async function settingsHref(
  orgId: OrgId,
  section: string,
): Promise<string> {
  const slug = await slugOf(orgId);
  return slug === null ? ORG_PICKER_PATH : settingsPath(slug, section);
}

export async function projectHref(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<string> {
  const slug = await slugOf(orgId);
  if (slug === null) return ORG_PICKER_PATH;

  const project = await projectRepo.findProjectById(orgId, projectId);
  return project ? projectPath(slug, project.slug) : orgPath(slug);
}

/**
 * The issue's own page. `projectId` is only a fallback for an issue that has
 * since been removed: the link then lands on its project rather than nowhere.
 */
export async function issueHref(
  orgId: OrgId,
  issueId: IssueId,
  projectId?: ProjectId,
): Promise<string> {
  const slug = await slugOf(orgId);
  if (slug === null) return ORG_PICKER_PATH;

  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) {
    return projectId === undefined
      ? orgPath(slug)
      : projectHref(orgId, projectId);
  }

  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  return project
    ? issuePath(slug, project.slug, issue.number)
    : orgPath(slug);
}

/** A comment has no page of its own; it lives on its issue's page. */
export async function commentHref(
  orgId: OrgId,
  commentId: CommentId,
): Promise<string> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  return comment ? issueHref(orgId, comment.issueId) : orgHref(orgId);
}

