new_block = '''/**
 * An inbox and its settings belong to one member. The role matrix lets every
 * role through `notification:read` / `notification:manage`, so on top of the
 * usual check the resource must be the actor's own — an owner gets no more
 * access to someone else's inbox than a viewer does.
 */
function assertOwnNotifications(
  actor: Actor,
  action: PermissionAction,
  orgId: OrgId,
  recipientId: UserId,
): void {
  assertCan(actor, action, notificationResource(orgId, recipientId));

  if (recipientId !== actor.userId) {
    throw new PermissionDeniedError(action, {
      allowed: false,
      action,
      resourceKind: "notification",
      reason: "denied_not_recipient",
    });
  }
}

export async function listNotifications(
  actor: Actor,
  input: ListNotificationsInput,
): Promise<Page<Notification>> {
  assertOrgScope(actor, input.orgId);
  assertOwnNotifications(
    actor,
    "notification:read",
    input.orgId,
    input.recipientId,
  );
  return notificationRepo.listNotifications(input);
}

export async function markRead(
  actor: Actor,
  input: MarkNotificationReadInput,
): Promise<Notification> {
  assertOrgScope(actor, input.orgId);

  const notification = requireFound(
    await notificationRepo.findNotificationById(
      input.orgId,
      input.notificationId,
    ),
    "Notification",
    input.notificationId,
  );
  assertOwnNotifications(
    actor,
    "notification:manage",
    input.orgId,
    notification.recipientId,
  );

  return notificationRepo.markRead(
    input.orgId,
    input.notificationId,
    toIsoTimestamp(new Date()),
  );
}

export async function markAllRead(
  actor: Actor,
  orgId: OrgId,
): Promise<number> {
  assertOrgScope(actor, orgId);
  assertOwnNotifications(actor, "notification:manage", orgId, actor.userId);
  return notificationRepo.markAllRead(
    orgId,
    actor.userId,
    toIsoTimestamp(new Date()),
  );
}

export async function updatePreference(
  actor: Actor,
  input: UpdateNotificationPreferenceInput,
): Promise<NotificationPreference> {
  assertOrgScope(actor, input.orgId);
  assertOwnNotifications(actor, "notification:manage", input.orgId, input.userId);
  return preferenceRepo.upsertPreference(input);
}

