fan = '''/**
 * What each limited resource is called in the alert that its refusal raises.
 * The title doubles as the identity of the alert: one unread alert per
 * resource is all the owner needs.
 */
const LIMIT_LABELS: Readonly<Record<LimitedResource, string>> = {
  seats: "seats",
  projects: "projects",
  issuesPerProject: "issues per project",
  storageMb: "storage",
  apiRequestsPerHour: "API requests",
  webhooks: "webhook endpoints",
};

/** Plan-limit alerts are checked-then-written, so they take turns. */
let limitAlerts: Promise<unknown> = Promise.resolve();

function inTurn<T>(task: () => Promise<T>): Promise<T> {
  const run = limitAlerts.then(task, task);
  limitAlerts = run.catch(() => undefined);
  return run;
