import * as usageService from "@/server/services/usage-service";
import * as notificationService from "@/server/services/notification-service";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { emit } from "@/lib/event-bus";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let t: Tenant;
let free: Tenant;

const list = (actor: any, recipientId: any, extra: any = {}) =>
  notificationService.listNotifications(actor, { orgId: actor.orgId, recipientId, unreadOnly: false, limit: 25, cursor: null, ...extra });

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("tmpv", "growth");
  free = await createTenant("tmpfree", "free");
  const unsub = searchService.registerSearchListeners();
  void unsub;
});
afterAll(() => cleanup());

describe("verify", () => {
  it("refuses others' inbox", async () => {
    await expect(list(t.actors.owner, t.userIds.member)).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(list(t.actors.admin, t.userIds.member)).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(list(t.actors.member, t.userIds.member)).resolves.toBeDefined();
    await expect(
      notificationService.updatePreference(t.actors.owner, { orgId: t.org.id, userId: t.userIds.member, kind: "issue_assigned", inApp: false, email: false, digestOnly: false }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("links + assign at creation + status change + mark all", async () => {
    const issue = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "Linked issue", assigneeId: t.userIds.viewer }),
    );
    const mine = await list(t.actors.viewer, t.userIds.viewer);
    expect(mine.items).toHaveLength(1);
    expect(mine.items[0]!.kind).toBe("issue_assigned");
    expect(mine.items[0]!.href).toBe(`/tmpv/projects/platform/issues/${issue.number}`);

    // own creation → nothing
    await issueService.createIssue(
      t.actors.viewer as any,
      issueInput(t.org.id, t.project.id, { title: "Self", assigneeId: t.userIds.member }),
    ).catch(() => undefined);
    await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "Self2", assigneeId: t.userIds.member }),
    );
    const memberInbox = await list(t.actors.member, t.userIds.member);
    expect(memberInbox.items.filter((n) => n.kind === "issue_assigned")).toHaveLength(0);

    // status change by someone else
    await issueService.changeIssueStatus(t.actors.admin, { orgId: t.org.id, issueId: issue.id, status: "in_progress" });
    const after = await list(t.actors.viewer, t.userIds.viewer);
    const sc = after.items.filter((n) => n.kind === "issue_status_changed");
    expect(sc).toHaveLength(1);
    expect(sc[0]!.href).toBe(`/tmpv/projects/platform/issues/${issue.number}`);
    // own change → nothing
    await issueService.changeIssueStatus(t.actors.viewer, { orgId: t.org.id, issueId: issue.id, status: "done" }).catch(() => undefined);

    // comment link + search hit links
    const comment = await commentService.createComment(t.actors.member, {
      orgId: t.org.id, issueId: issue.id, body: "SearchableCommentZ", parentId: null, mentionedUserIds: [t.userIds.admin],
    });
    const hits = await searchService.search(t.actors.member, { orgId: t.org.id, q: "SearchableCommentZ", kinds: ["comment"], limit: 25, cursor: null });
    expect(hits.items[0]!.href).toBe(`/tmpv/projects/platform/issues/${issue.number}`);
    const ih = await searchService.search(t.actors.member, { orgId: t.org.id, q: "Linked issue", kinds: ["issue"], limit: 25, cursor: null });
    expect(ih.items[0]!.href).toBe(`/tmpv/projects/platform/issues/${issue.number}`);
    const adminInbox = await list(t.actors.admin, t.userIds.admin);
    expect(adminInbox.items.every((n) => n.href.startsWith("/tmpv/projects/platform/issues/"))).toBe(true);
    void comment;

    // markAllRead only own
    const n = await notificationService.markAllRead(t.actors.viewer, t.org.id);
    expect(n).toBeGreaterThan(0);
    const adm = await list(t.actors.admin, t.userIds.admin, { unreadOnly: true });
    expect(adm.total).toBeGreaterThan(0);

    // markRead someone else's
    await expect(
      notificationService.markRead(t.actors.viewer, { orgId: t.org.id, notificationId: adminInbox.items[0]!.id }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("member joined → owner; in_app off hidden; paging", async () => {
    await emit("member.joined", { orgId: t.org.id, actorId: t.userIds.viewer, occurredAt: new Date().toISOString() as any, memberId: "m1" as any, userId: t.userIds.viewer, role: "viewer" });
    const own = await list(t.actors.owner, t.userIds.owner, { kind: ["member_joined"] });
    expect(own.items).toHaveLength(1);
    expect(own.items[0]!.href).toBe("/tmpv/settings/members");
    const v = await list(t.actors.viewer, t.userIds.viewer, { kind: ["member_joined"] });
    expect(v.items).toHaveLength(0);

    await preferenceRepo.upsertPreference({ orgId: t.org.id, userId: t.userIds.admin, kind: "comment_created", inApp: false, email: true, digestOnly: false });
    const rows = await notificationService.notify(t.org.id, "comment_created", [t.userIds.admin], { title: "x", body: "x", href: "/x", actorId: null });
    expect(rows).toHaveLength(1);
    const a = await list(t.actors.admin, t.userIds.admin, { kind: ["comment_created"] });
    expect(a.items.some((n) => n.id === rows[0]!.id)).toBe(false);

    // paging
    for (let i = 0; i < 130; i += 1) {
      await notificationService.notify(t.org.id, "member_joined", [t.userIds.member], { title: `p${i}`, body: "b", href: "/x", actorId: null });
    }
    const seen = new Set<string>();
    let cursor: string | null = null;
    let total = 0;
    do {
      const page: any = await list(t.actors.member, t.userIds.member, { kind: ["member_joined"], limit: 40, cursor });
      total = page.total;
      for (const n of page.items) { expect(seen.has(n.id)).toBe(false); seen.add(n.id); }
      cursor = page.nextCursor;
    } while (cursor);
    expect(seen.size).toBe(130);
    expect(total).toBe(130);
  });

  it("plan limit alert", async () => {
    // free: 2 projects
    await projectService.createProject(free.actors.owner, { orgId: free.org.id, name: "A", slug: "a", key: "AAA", description: null, visibility: "org", leadId: null, color: "#6366f1", targetDate: null } as any).catch(() => undefined);
    const mk = (n: string) => projectService.createProject(free.actors.member, { orgId: free.org.id, name: n, slug: n, key: n.toUpperCase(), description: null, visibility: "org", leadId: null, color: "#6366f1", targetDate: null } as any);
    await mk("bb").catch(() => undefined);
    await expect(mk("cc")).rejects.toThrow();
    await expect(mk("dd")).rejects.toThrow();
    let inbox = await list(free.actors.owner, free.userIds.owner, { kind: ["plan_limit_reached"] });
    expect(inbox.items).toHaveLength(1);
    expect(inbox.items[0]!.href).toBe("/tmpfree/settings/billing");
    await notificationService.markRead(free.actors.owner, { orgId: free.org.id, notificationId: inbox.items[0]!.id });
    await expect(mk("ee")).rejects.toThrow();
    inbox = await list(free.actors.owner, free.userIds.owner, { kind: ["plan_limit_reached"] });
    expect(inbox.items).toHaveLength(2);
    // seats separately
    await expect(invitationService.inviteMember(free.actors.admin, { orgId: free.org.id, email: "z@z.test", role: "member" } as any)).rejects.toThrow();
    inbox = await list(free.actors.owner, free.userIds.owner, { kind: ["plan_limit_reached"] });
    expect(inbox.items).toHaveLength(3);
    await usageService.recomputeUsage(free.org.id);
    inbox = await list(free.actors.owner, free.userIds.owner, { kind: ["plan_limit_reached"] });
    expect(inbox.items).toHaveLength(3);
    void notificationRepo;
  });
});
EOF
